const Seq = (()=>{
const safe=x=>Number.isFinite(x)&&Math.abs(x)<1e100;
function term(s,n){if(!Number.isInteger(n)||n<0)return NaN;switch(s.kind){case'arith':return s.u+n*s.r;case'geo':return n===0?s.u:s.u*s.q**n;case'quad':return s.a*n*n+s.b*n+s.c;case'inverse':return s.L+s.A/(n+1);case'affine':if(s.q===1)return s.u+n*s.d;return s.u*s.q**n+s.d*(1-s.q**n)/(1-s.q);}}
function terms(s,N){let out=[];for(let n=0;n<=N;n++){let v=term(s,n);if(!safe(v))break;out.push(v)}return out}
function sum(s,p,m){if(!Number.isInteger(p)||!Number.isInteger(m)||p<0||m<p||m>10000)return NaN;let total=0;for(let n=p;n<=m;n++)total+=term(s,n);return total}
function threshold(s,T,op,max=10000){for(let n=0;n<=max;n++){let v=term(s,n);if(!safe(v)||(s.kind==='geo'&&s.u!==0&&s.q!==0&&v===0)||(s.kind==='inverse'&&s.A!==0&&v===s.L)||(s.kind==='affine'&&s.q!==0&&Math.abs(s.q)<1&&s.u!==s.d/(1-s.q)&&v===s.d/(1-s.q)))return {status:'precision',n};if(op==='ge'?v>=T:v<=T)return{status:'found',n,v,prev:n?term(s,n-1):null}}return{status:'notfound',max}}
function variation(s){let delta;if(s.kind==='arith')delta=s.r;else if(s.kind==='inverse')delta=-s.A;else if(s.kind==='quad'){if(s.a===0)delta=s.b;else return `uₙ₊₁ − uₙ = ${2*s.a}n + (${s.a+s.b}). Étudier le signe de cette expression pour les entiers n ≥ 0 ; le sens peut changer. Une différence nulle donne deux termes consécutifs égaux.`;}else{delta=s.u*(s.q-1)+(s.kind==='affine'?s.d:0);if(delta!==0&&s.q<0)return 'Les différences successives alternent de signe : la suite n’est ni croissante ni décroissante.';if(delta!==0&&s.q===0)return `La suite ${delta>0?'augmente':'diminue'} entre les rangs 0 et 1, puis reste constante. Elle est ${delta>0?'croissante':'décroissante'} au sens large.`;}
return delta===0?'Tous les termes sont égaux : la suite est constante.':`Pour tout n ≥ 0, uₙ₊₁ − uₙ est ${delta>0?'positif':'négatif'} : la suite est strictement ${delta>0?'croissante ↗':'décroissante ↘'}.`;}
function limit(s){if(s.kind==='arith')return s.r===0?`Constante : limite ${s.u}.`:`Les termes tendent vers ${s.r>0?'+∞':'−∞'}.`;if(s.kind==='inverse')return `Les termes se rapprochent de L = ${s.L} car A/(n + 1) tend vers 0.`;if(s.kind==='quad'){let lead=s.a||s.b;return lead?`Le terme dominant donne une limite ${lead>0?'+∞':'−∞'}.`:`Constante : limite ${s.c}.`;}
let q=s.q,L=s.kind==='affine'&&q!==1?s.d/(1-q):0,C=s.u-L;if(q===1)return s.kind==='affine'&&s.d!==0?`Ajout constant : limite ${s.d>0?'+∞':'−∞'}.`:`Constante : limite ${s.u}.`;if(C===0)return `Constante : limite ${L}.`;if(Math.abs(q)<1)return `L’amplitude géométrique diminue : les termes tendent vers ${L}.`;if(q>1)return `Les termes tendent vers ${C>0?'+∞':'−∞'}.`;return q===-1?'Deux valeurs distinctes alternent : absence de limite.':'Les signes autour du point fixe alternent et l’amplitude grandit : absence de limite.';}
return{term,terms,sum,threshold,variation,limit,safe};})();
if(typeof module!=='undefined')module.exports=Seq;
